// IC-03: the season snapshot `packages/seed/snapshot/season-2026A.json`. Screens, mocks, the README
// and the film read it; no one hard-codes a figure. Every value is generated by `packages/seed` and
// every hash is computed. Provenance of everything in it is `seeded`.
import { z } from "zod";
import {
  BatchItem,
  EngineOutput,
  InvoiceQuote,
  Lot,
  ProofBundle,
  RatifiedRateCard,
  SignedApproval,
} from "./domain.js";
import { Honorifics, Plot } from "./entities.js";
import {
  CopyColor,
  Grade,
  HoldGate,
  HoldKind,
  HoldResolutionKind,
  InvoiceStatus,
  MemberLineState,
  PayoutItemStatus,
  PayRunState,
  Rail,
  ReceiverKind,
  SignatureMark,
  Station,
} from "./enums.js";
import {
  Fx,
  Grams,
  IsoDate,
  IsoDateTime,
  Lang,
  MemberNo,
  NonNegCents,
  PhotoId,
  PlotNo,
  RunSlug,
  SeasonCode,
  SeasonLabel,
  Sha256Hex,
  SlipSerial,
  Uuid,
} from "./primitives.js";

export const SnapshotOfficer = z.strictObject({
  role: z.enum(["TREASURER", "CHAIR", "SECRETARY", "CLERK"]),
  name: z.string(),
  shortName: z.string(),
  initials: z.string().regex(/^[A-Z]{2}$/),
  persona: z.string(),
  keyId: z.string().nullable(),
});
export type SnapshotOfficer = z.infer<typeof SnapshotOfficer>;

export const SnapshotLoan = z.strictObject({
  ref: z.string(),
  outstandingCentavos: z.int().nonnegative(),
  authorityToDeduct: z.boolean(),
});

export const SnapshotAdvance = z.strictObject({
  voucherNo: z.string().nullable(),
  outstandingCentavos: z.int().nonnegative(),
});

export const SnapshotMember = z.strictObject({
  id: Uuid,
  memberNo: MemberNo,
  displayName: z.string(),
  nickname: z.string().nullable(),
  /** How the console names them: "Nang Celing", "Merlyn Ponce". */
  consoleName: z.string(),
  addressAs: Honorifics,
  nameOnSlip: z.string(),
  gender: z.enum(["F", "M"]),
  lang: Lang,
  rail: Rail,
  receiverKind: ReceiverKind,
  /** Seeded alias; the runtime maps memberNo → PP_RECEIVERS (env only, never in the repo). */
  receiverAlias: z.string().nullable(),
  receiverMasked: z.string().nullable(),
  signsWith: z.enum(["SIGNATURE", "THUMBMARK"]),
  audioFirst: z.boolean(),
  /** One of the nine members named in register §2. */
  named: z.boolean(),
  demoRole: z.string().nullable(),
  plots: z.array(Plot),
  cbuPaidUpCentavos: z.int().nonnegative(),
  loans: z.array(SnapshotLoan),
  advances: z.array(SnapshotAdvance),
  slipSerials: z.array(SlipSerial),
});
export type SnapshotMember = z.infer<typeof SnapshotMember>;

export const SnapshotMark = z.strictObject({
  markId: z.string(),
  text: z.string(),
  ruleId: z.string(),
  writtenCentavos: z.int().nonnegative().nullable(),
  documentRef: z.string().nullable(),
});

export const SnapshotSlip = z.strictObject({
  rowId: Uuid,
  documentId: Uuid,
  serial: SlipSerial,
  copy: CopyColor,
  photoId: PhotoId,
  position: z.enum(["TL", "TR", "BL", "BR"]),
  replaySet: z.boolean(),
  slipDate: IsoDate,
  memberNo: MemberNo,
  plotNo: PlotNo,
  station: Station,
  sacks: z.string(),
  grossG: Grams,
  tareG: Grams,
  netG: Grams,
  mcPctTenths: z.int().nonnegative(),
  mcLessG: Grams,
  payableG: Grams,
  grade: Grade,
  clerkInitials: z.string(),
  signature: SignatureMark,
  /** Box 1–13 exactly as Jessie writes them (what WS-MEDIA renders and the reads must return). */
  boxes: z.strictObject({
    "1": z.string(),
    "2": z.string(),
    "3": z.string(),
    "4": z.string(),
    "5": z.string(),
    "6": z.string(),
    "7": z.string(),
    "8": z.string(),
    "9": z.string(),
    "10": z.string(),
    "11": z.string(),
    "12": z.string(),
    "13": z.array(z.string()).max(2),
  }),
  marks: z.array(SnapshotMark),
  /** Instruction-like margin text (slip 0449 only). Quarantined: never enters a prompt. */
  marginNote: z.string().nullable(),
  artifacts: z.array(z.enum(["WATER_STAIN"])),
});
export type SnapshotSlip = z.infer<typeof SnapshotSlip>;

export const SnapshotPhoto = z.strictObject({
  photoId: PhotoId,
  documentId: Uuid,
  set: z.enum(["REPLAY", "EARLIER"]),
  file: z.string(),
  slips: z
    .array(
      z.strictObject({ position: z.enum(["TL", "TR", "BL", "BR"]), serial: SlipSerial, copy: CopyColor }),
    )
    .length(4),
  capturedOn: IsoDate,
  /** Earlier photos carry their own read date; the replay set is read in the recorded run. */
  readOn: IsoDate.nullable(),
  readProvenance: z.enum(["replay", "seeded"]),
  /** sha256 of the photo's canonical slip manifest (the image file's own sha256 lands with IC-11). */
  manifestSha256: Sha256Hex,
});
export type SnapshotPhoto = z.infer<typeof SnapshotPhoto>;

export const SnapshotLogbookPage = z.strictObject({
  page: z.int().positive(),
  month: z.string().regex(/^\d{4}-\d{2}$/),
  lines: z.array(
    z.strictObject({
      lineNo: z.int().positive(),
      serial: SlipSerial,
      memberNo: MemberNo,
      netKgText: z.string(),
      remark: z.string().nullable(),
    }),
  ),
});
export type SnapshotLogbookPage = z.infer<typeof SnapshotLogbookPage>;

export const SnapshotHold = z.strictObject({
  label: z.string(),
  key: z.string(),
  kind: HoldKind,
  gate: HoldGate,
  memberNo: MemberNo.nullable(),
  serials: z.array(SlipSerial),
  engineLine: z.string(),
  /** Pencil, no digits: the design's reference line, seeded until the recorded run replaces it. */
  claudeLine: z.string().nullable(),
  resolvedWith: HoldResolutionKind.nullable(),
  resolvedLine: z.string().nullable(),
  resolvedBy: z.string().nullable(),
  resolvedAt: IsoDateTime.nullable(),
});
export type SnapshotHold = z.infer<typeof SnapshotHold>;

export const SnapshotItem = BatchItem.extend({
  memberNo: MemberNo,
  payoutItemId: z.string(),
  status: PayoutItemStatus,
  eventId: z.string().nullable(),
  lineState: MemberLineState,
});
export type SnapshotItem = z.infer<typeof SnapshotItem>;

export const SnapshotFigures = z.strictObject({
  invoiceCents: NonNegCents,
  premiumPoolCents: NonNegCents,
  bonusPoolCents: NonNegCents,
  disbursementCents: NonNegCents,
  poolCents: NonNegCents,
  grossCents: NonNegCents,
  deductionsCents: NonNegCents,
  creditsCents: NonNegCents,
  netCents: NonNegCents,
  onRailNetCents: NonNegCents,
  onRailMembers: z.int(),
  cashNetCents: NonNegCents,
  cashMembers: z.int(),
  redirectedCents: NonNegCents,
  redirectedDuplicateCents: NonNegCents,
  redirectedCreditCents: NonNegCents,
  othersGainOnCountOnceCents: z.int(),
  batchItemCount: z.int(),
  batchTotalCents: NonNegCents,
  endPaidMembers: z.int(),
  endPaidCents: NonNegCents,
  endCashMembers: z.int(),
  endCashCents: NonNegCents,
  feesSandboxCents: NonNegCents,
  feesProductionCents: NonNegCents,
  verifiedG: Grams,
  verifiedGrade1G: Grams,
  shippedG: Grams,
  grade1ShippedG: Grams,
  shrinkOnceBp: z.int(),
  shrinkTwiceBp: z.int(),
  members: z.int(),
  women: z.int(),
  slipImages: z.int(),
  photos: z.int(),
  /** Display strings for UI that may not import `domain`. */
  display: z.record(z.string(), z.string()),
});
export type SnapshotFigures = z.infer<typeof SnapshotFigures>;

export const SnapshotRun = z.strictObject({
  id: Uuid,
  runSeq: z.int().positive(),
  runSlug: RunSlug,
  state: PayRunState,
  recordedOn: IsoDate,
  fx: Fx,
  cashDay: IsoDate,
  quote: InvoiceQuote,
  quoteSha256: Sha256Hex,
  invoice: z.strictObject({
    invoiceNumber: z.string().max(25),
    reference: z.string(),
    note: z.string(),
    invoiceDate: IsoDate,
    dueDate: IsoDate,
    autoCancelOn: IsoDate,
    status: InvoiceStatus,
    amountCents: NonNegCents,
    dueCents: NonNegCents,
    provenance: z.enum(["simulated_rail", "seeded"]),
    pesoEstimate: z.string(),
  }),
  senderBatchId: z.string(),
  paypalRequestId: Sha256Hex,
  batchNote: z.string(),
  batchSha256: Sha256Hex,
  items: z.array(SnapshotItem),
  approvals: z.array(SignedApproval),
  chairNeeded: z.strictObject({ required: z.boolean(), reasons: z.array(z.string()) }),
  lineStates: z.record(z.string(), MemberLineState),
});
export type SnapshotRun = z.infer<typeof SnapshotRun>;

export const SeasonSnapshot = z.strictObject({
  v: z.literal(1),
  provenance: z.literal("seeded"),
  generator: z.strictObject({ name: z.string(), version: z.string(), attempt: z.int().nonnegative() }),
  coop: z.strictObject({
    id: Uuid,
    name: z.string(),
    shortName: z.string(),
    locality: z.string(),
    region: z.string(),
    commodity: z.literal("cacao"),
    stations: z.array(z.strictObject({ station: Station, name: z.string() })),
  }),
  officers: z.array(SnapshotOfficer),
  payer: z.strictObject({
    name: z.string(),
    shortName: z.string(),
    city: z.string(),
    contactName: z.string(),
    contactTitle: z.string(),
  }),
  season: z.strictObject({
    id: Uuid,
    code: SeasonCode,
    label: SeasonLabel,
    opensOn: IsoDate,
    closesOn: IsoDate,
    firstSlipOn: IsoDate,
    lastSlipOn: IsoDate,
    serialFirst: SlipSerial,
    serialLast: SlipSerial,
  }),
  lot: Lot.extend({ id: Uuid, buyer: z.string() }),
  rateCard: RatifiedRateCard.extend({
    id: Uuid,
    textLayer: z.strictObject({
      pages: z.array(z.strictObject({ page: z.int().positive(), lines: z.array(z.string()) })),
    }),
  }),
  fx: Fx,
  members: z.array(SnapshotMember),
  slips: z.array(SnapshotSlip),
  photos: z.array(SnapshotPhoto),
  logbook: z.array(SnapshotLogbookPage),
  /** Engine output at three checkpoints of the review: after reading, after slip 0462, and resolved. */
  checkpoints: z.strictObject({
    read: EngineOutput,
    byHand: EngineOutput,
    resolved: EngineOutput,
  }),
  holds: z.array(SnapshotHold),
  quarantineNotices: z.array(z.strictObject({ serial: SlipSerial, photoId: PhotoId, notice: z.string() })),
  run: SnapshotRun,
  figures: SnapshotFigures,
  proof: ProofBundle,
});
export type SeasonSnapshot = z.infer<typeof SeasonSnapshot>;
